import React from 'react';

/**
 * Tarjeta de un producto en la grilla del menú. Es "arrastrable" cuando se
 * está viendo una categoría puntual (para reordenar), no en la vista "Todas".
 */
const ProductCard = ({ product, draggable, isDragging, onDragStart, onDrop, onToggleAvailability, onDuplicate, onEdit, onDelete }) => (
  <div
    className="bg-slate-800 border border-slate-700 rounded-2xl p-5 transition-opacity"
    draggable={draggable}
    onDragStart={onDragStart}
    onDragOver={(e) => e.preventDefault()}
    onDrop={onDrop}
    style={{ cursor: draggable ? 'grab' : 'default', opacity: isDragging ? 0.4 : 1 }}
  >
    <div
      className="w-full h-[140px] rounded-[10px] bg-slate-700 bg-cover bg-center mb-3 flex items-center justify-center text-4xl relative"
      style={product.image_url ? { backgroundImage: `url(${product.image_url})` } : undefined}
    >
      {!product.image_url && '🍽️'}
      {product.is_combo && (
        <span className="absolute top-2 left-2 bg-purple-500 text-white text-[10px] font-bold px-2 py-1 rounded-md">
          🍔 COMBO
        </span>
      )}
    </div>

    <div className="flex justify-between mb-1.5">
      <h4 className="text-slate-200 text-[15px]">{product.name}</h4>
      <span className="text-amber-400 font-bold">${product.price?.toFixed(2)}</span>
    </div>
    <p className="text-slate-400 text-xs mb-1.5">{product.categoryName}</p>
    {product.modifiers?.length > 0 && (
      <p className="text-purple-500 text-[11px] mb-2.5">
        ⚙️ {product.modifiers.map((m) => m.name).join(' · ')}
      </p>
    )}

    <div className="flex gap-1.5 flex-wrap">
      <button
        onClick={onToggleAvailability}
        className={`px-2.5 py-1.5 rounded-md border-none text-[11px] font-semibold cursor-pointer ${
          product.is_available ? 'bg-emerald-500/10 text-emerald-500' : 'bg-red-500/10 text-red-500'
        }`}
      >
        {product.is_available ? '✓ Disponible' : '✗ No disponible'}
      </button>
      <button onClick={onDuplicate} className="px-2.5 py-1.5 rounded-md border-none bg-slate-400/15 text-slate-300 text-[11px] font-semibold cursor-pointer">
        📋 Duplicar
      </button>
      <button onClick={onEdit} className="px-2.5 py-1.5 rounded-md border-none bg-sky-400/10 text-sky-400 text-[11px] font-semibold cursor-pointer">
        ✏️ Editar
      </button>
      <button onClick={onDelete} className="px-2.5 py-1.5 rounded-md border-none bg-red-500/10 text-red-500 text-[11px] font-semibold cursor-pointer">
        🗑️ Eliminar
      </button>
    </div>
  </div>
);

export default ProductCard;
